"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["108957"],{835619(e){e.exports=JSON.parse('{"tag":{"label":"servicenow-otto","permalink":"/sdk/4.12.2/tags/servicenow-otto","allTagsPath":"/sdk/4.12.2/tags","count":5,"items":[{"id":"guides/nowassist-skills-guide","title":"AI Skills Guide","description":"Create and configure AI Skills using the NowAssistSkillConfig API in the Fluent SDK. Skills use configured prompts to generate AI responses from an LLM, optionally enriched by inputs and tools (script, inline script, web search, subflows, flow actions, decision branches). This guide covers skill structure, inputs, prompts, deployment, and naming conventions. Requires SDK 4.6.0 or higher.","permalink":"/sdk/4.12.2/guides/nowassist-skills-guide"},{"id":"api/aiagent-api","title":"AiAgent","description":"Configure an AI Agent record. AI Agents are intelligent agents that execute tools,","permalink":"/sdk/4.12.2/api/aiagent-api"},{"id":"api/aiagenticworkflow-api","title":"AiAgenticWorkflow","description":"Configure an AI Agentic Workflow record. AI Agentic Workflows orchestrate multiple","permalink":"/sdk/4.12.2/api/aiagenticworkflow-api"},{"id":"guides/building-ai-agents-guide","title":"Building AI Agents Guide","description":"Build and configure ServiceNow AI Agents and AI Agentic Workflows using the Fluent SDK. AI Agents perform tasks with tools (CRUD, script, OOB, reference-based), while AI Agentic Workflows orchestrate multiple agents as a team. This guide covers agent structure, authentication, triggers, ACL deployment, and workflow configuration. Requires SDK 4.4.0 or higher.","permalink":"/sdk/4.12.2/guides/building-ai-agents-guide"},{"id":"api/nowassistskillconfig-api","title":"NowAssistSkillConfig","description":"Branding note: \\"Now Assist\\" has been rebranded to \\"ServiceNow Otto.\\" These names refer to the same product. All technical identifiers (table names, field names, string literals like \\"Now Assist Panel\\", nowassistdeployment) remain unchanged \u2014 use them exactly as-is in code.","permalink":"/sdk/4.12.2/api/nowassistskillconfig-api"}],"unlisted":false}}')}}]);